import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Enseignant","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/enseignant/index.md","filePath":"src/guide/enseignant/index.md"}'),i={name:"guide/enseignant/index.md"};function r(o,e,l,d,u,p){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="enseignant" tabindex="-1">Enseignant <a class="header-anchor" href="#enseignant" aria-label="Permalink to &quot;Enseignant&quot;">​</a></h1><p>En tant qu&#39;enseignant, vous ne voyez que vos propres classes et matières : celles pour lesquelles l&#39;administrateur vous a explicitement affecté (côté administration, menu <strong>Paramétrage scolaire → Affectations enseignants</strong>). Si une classe ou une matière n&#39;apparaît pas dans vos listes déroulantes, c&#39;est qu&#39;aucune affectation ne vous relie encore à elle — signalez-le à l&#39;administrateur.</p><p>Si vous êtes désigné <strong>professeur principal</strong> d&#39;une classe, vous disposez en plus d&#39;une vue consolidée de cette classe et des appréciations générales de fin de période, décrites dans la troisième page ci-dessous.</p><p>Ce guide couvre quatre activités :</p><table tabindex="0"><thead><tr><th>Page</th><th>Ce que vous y faites</th></tr></thead><tbody><tr><td><a href="/era-guide/guide/enseignant/notes-et-evaluations.html">Notes et évaluations</a></td><td>Créer une évaluation, saisir les notes, renseigner les observations de compétences</td></tr><tr><td><a href="/era-guide/guide/enseignant/bulletins-et-cahier-texte.html">Bulletins et cahier de textes</a></td><td>Rédiger les appréciations de bulletin, tenir le cahier de textes</td></tr><tr><td><a href="/era-guide/guide/enseignant/registre-et-emploi-du-temps.html">Registre et emploi du temps</a></td><td>Consulter le registre de votre classe (professeur principal) et votre propre emploi du temps</td></tr><tr><td><a href="/era-guide/guide/enseignant/notes-superieur.html">Notes des EC (supérieur)</a></td><td>Saisir les notes de vos EC dans un établissement d&#39;enseignement supérieur</td></tr></tbody></table><h2 id="l-appel-et-les-justificatifs" tabindex="-1">L&#39;appel et les justificatifs <a class="header-anchor" href="#l-appel-et-les-justificatifs" aria-label="Permalink to &quot;L&#39;appel et les justificatifs&quot;">​</a></h2><p>Vous faites aussi l&#39;appel de vos classes — depuis le bouton <strong>Faire l&#39;appel</strong> de votre tableau de bord, ou <strong>Vie scolaire → Présences</strong> — et vous pouvez traiter les justificatifs d&#39;absence envoyés par les familles pour vos classes. Les deux sont décrits dans <a href="/era-guide/guide/vie-scolaire/presences-et-absences.html">Présences et absences</a>, dans le guide de la vie scolaire.</p><div class="info custom-block"><p class="custom-block-title">Les parents ne sont pas prévenus de chaque note</p><p>Enregistrer une note n&#39;envoie rien aux familles : elles découvrent les résultats de la période avec le bulletin publié par l&#39;administration, et consultent les moyennes dans leur espace entre-temps. Une absence non justifiée, en revanche, les prévient dès que l&#39;appel est enregistré.</p></div><p>Pour tout ce qui concerne votre compte personnel (connexion, profil, sécurité, notifications), commun à tous les rôles, voir <a href="/era-guide/guide/prise-en-main.html">Bien démarrer</a>.</p>',9)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
